function defaultState(){return{version:2,stays:[],profiles:[{id:uid(),name:'Me',citizenships:[],enabledRules:['schengen']}],activeProfileId:null};}
function loadState(){try{let v=JSON.parse(localStorage.getItem(APP_KEY));if(v){normalizeState(v);return v}}catch{};let d=defaultState();try{let legacy=JSON.parse(localStorage.getItem(LEGACY_KEY))||[];d.stays=legacy.map(s=>({...s,status:s.status||'actual',profileId:s.profileId||null}))}catch{};d.activeProfileId=d.profiles[0].id;return d}
function normalizeState(v){v.version=2;v.stays=Array.isArray(v.stays)?v.stays:[];v.profiles=Array.isArray(v.profiles)&&v.profiles.length?v.profiles:defaultState().profiles;v.activeProfileId=v.activeProfileId||v.profiles[0].id;v.profiles.forEach(p=>{p.citizenships=p.citizenships||[];p.enabledRules=p.enabledRules||['schengen']});v.stays.forEach(s=>{s.status=s.status||'actual';if(s.profileId===undefined)s.profileId=null})}
function persist(noCloud=false){localStorage.setItem(APP_KEY,JSON.stringify(state));if(!noCloud&&cloudSession&&getCloudConfig().autoSync){clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>cloudPush(true),700)}}
function uid(){return(Date.now().toString(36)+Math.random().toString(36).slice(2,9))}
function isoDate(d){return new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())).toISOString().slice(0,10)}
function parseDate(s){let[y,m,d]=s.split('-').map(Number);return new Date(Date.UTC(y,m-1,d))}
function addDays(d,n){let x=new Date(d);x.setUTCDate(x.getUTCDate()+n);return x}
function addMonths(d,n){let x=new Date(d);x.setUTCMonth(x.getUTCMonth()+n);return x}
function startOfMonth(d){return new Date(Date.UTC(d.getFullYear(),d.getMonth(),1))}
function dayKey(d){return d.toISOString().slice(0,10)}
function diffDays(a,b){return Math.round((parseDate(b)-parseDate(a))/86400000)}
function daysInclusive(a,b){return diffDays(a,b)+1}
function fmt(s,o={day:'numeric',month:'short',year:'numeric'}){return parseDate(s).toLocaleDateString(undefined,{...o,timeZone:'UTC'})}
function fmtObj(d,o={day:'numeric',month:'short',year:'numeric'}){return d.toLocaleDateString(undefined,{...o,timeZone:'UTC'})}
function flag(c){return c?[...c.toUpperCase()].map(x=>String.fromCodePoint(127397+x.charCodeAt())).join(''):''}
function flagUrl(c,w=80){return c?`https://flagcdn.com/w${w}/${String(c).toLowerCase()}.png`:''}
function flagHtml(c,cls='flag-img'){if(!c)return'';let code=String(c).toUpperCase();return`<img class="${esc(cls)}" src="${flagUrl(code)}" alt="${code} flag" loading="lazy" onerror="this.style.display='none'">`}
function countryByName(n=''){return COUNTRIES.find(c=>c.name.toLowerCase()===n.trim().toLowerCase())}
function countryByCode(c){return COUNTRIES.find(x=>x.code===c)}
function esc(v=''){return String(v).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]))}
function plural(n,w){return`${n} ${w}${n===1?'':'s'}`}
function activeProfile(){return state.profiles.find(p=>p.id===state.activeProfileId)||state.profiles[0]}
function isSchengenExemptProfile(p=activeProfile()){return !!p&&p.citizenships.some(c=>EU_EEA_CH.has(c))}
function staysForProfile(profileId=state.activeProfileId){return state.stays.filter(s=>!s.profileId||s.profileId===profileId)}
function datesForStay(s,min=null,max=null){let a=parseDate(s.start),b=parseDate(s.end),lo=min?parseDate(min):a,hi=max?parseDate(max):b,start=a>lo?a:lo,end=b<hi?b:hi,out=[];for(let d=start;d<=end;d=addDays(d,1))out.push(dayKey(d));return out}
function travelDaySet(list=state.stays){let set=new Set();list.forEach(s=>datesForStay(s).forEach(d=>set.add(d)));return set}
function schengenDaySet(min=null,max=null,profileId=state.activeProfileId,extra=[]){let set=new Set();[...staysForProfile(profileId),...extra].forEach(s=>{if(SCHENGEN.has(s.countryCode)&&!s.schengenExempt)datesForStay(s,min,max).forEach(d=>set.add(d))});return set}
function rollingStatus(check,profileId=state.activeProfileId,extra=[]){let end=parseDate(check),start=addDays(end,-179),set=schengenDaySet(dayKey(start),dayKey(end),profileId,extra),used=set.size;return{start,end,used,remaining:90-used}}
function statusForUsed(n){if(n>90)return{kind:'bad',label:'OVER',text:`Your records show ${n} Schengen days in this rolling 180-day window.`};if(n>=86)return{kind:'bad',label:'VERY CLOSE',text:`Only ${90-n} Schengen days remain in this rolling window.`};if(n>=75)return{kind:'warn',label:'WATCH',text:`You have ${90-n} Schengen days remaining in this rolling window.`};return{kind:'good',label:'OK',text:`You have ${90-n} Schengen days remaining in this rolling window.`}}
function firstOverstay(from,horizon=500,profileId=state.activeProfileId,extra=[]){let d=parseDate(from);for(let i=0;i<=horizon;i++,d=addDays(d,1)){let r=rollingStatus(dayKey(d),profileId,extra);if(r.used>90)return{date:dayKey(d),used:r.used}}return null}
function maxContinuousSchengen(entry,profileId=state.activeProfileId){let extra=[],last=null;for(let i=0;i<180;i++){let d=dayKey(addDays(parseDate(entry),i)),trial={id:'planner',countryCode:'FR',countryName:'Schengen',start:entry,end:d,schengenExempt:false,status:'planned',profileId};let r=rollingStatus(d,profileId,[trial]);if(r.used>90)break;last=d}return last?daysInclusive(entry,last):0}
function earliestOneDayEntry(from,profileId=state.activeProfileId,extra=[]){let d=parseDate(from);for(let i=0;i<730;i++,d=addDays(d,1)){let k=dayKey(d),trial={id:'reentry',countryCode:'FR',countryName:'Schengen',start:k,end:k,schengenExempt:false,status:'planned',profileId};if(rollingStatus(k,profileId,[...extra,trial]).used<=90)return k}return null}
function findGaps(){let source=staysForProfile(state.activeProfileId);if(source.length<2)return[];let arr=[...source].sort((a,b)=>a.start.localeCompare(b.start)||a.end.localeCompare(b.end)),gaps=[],curEnd=arr[0].end,prev=arr[0];for(let i=1;i<arr.length;i++){let s=arr[i];if(parseDate(s.start)>addDays(parseDate(curEnd),1)){let missingStart=dayKey(addDays(parseDate(curEnd),1)),missingEnd=dayKey(addDays(parseDate(s.start),-1)),gs=curEnd,ge=s.start;gaps.push({start:gs,end:ge,days:daysInclusive(gs,ge),missingStart,missingEnd,missingDays:daysInclusive(missingStart,missingEnd),prev,next:s})}if(s.end>curEnd){curEnd=s.end;prev=s}}return gaps}
